function countAndSay(n) {
  let current = "1";
  for (let step = 1; step < n; step++) {
    let next = "";
    let i = 0;
    while (i < current.length) {
      let j = i;
      while (j < current.length && current[j] === current[i]) {
        j++;
      }
      next += String(j - i) + current[i];
      i = j;
    }
    current = next;
  }
  return current;
}

brute:
function countAndSay(n) {
  if (n === 1) return "1";
  const previous = countAndSay(n - 1);
  return previous.replace(/(\d)\1*/g, block => block.length + block[0]);
}

